// Hook tipado com TanStack Query
import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import type { components } from "@/lib/api/schema";
import client from "@/lib/api/client";

type AgentConfig = components["schemas"]["AgentConfigResponse"];

export function useAgent(
  id: string,
  options?: Omit<UseQueryOptions<AgentConfig>, "queryKey" | "queryFn">,
) {
  return useQuery<AgentConfig>({
    queryKey: ["agent", id],
    queryFn: async () => {
      const res = await client.GET("/api/v1/configs/{config_id}", {
        params: { path: { config_id: id } },
      });
      if (res.error) throw new Error("Falha ao carregar agente");
      return res.data!;
    },
    staleTime: 30_000,
    ...options,
  });
}
